insert into public.announcements (id, title, category, priority, body, published, publish_at, expires_at, audience, created_at) values
  ('n1', 'Australia July 2026 Intake Now Open', 'Admissions', 'High', 'Applications are now open for the July 2026 intake at our partner universities across Australia, including Melbourne, Monash and Sydney. Submit early to secure priority assessment.', true, '2026-10-20T05:16:00.000Z', '2026-12-07T05:02:00.000Z', null, '2026-10-19T05:18:00.000Z'),
  ('n2', 'UK Student Visa Financial Requirements Updated', 'Visa Updates', 'Medium', 'UKVI has revised the maintenance funds requirement for student visa applicants. Please review the updated checklist before lodging new applications.', true, '2026-10-18T05:29:00.000Z', '2026-11-17T04:57:00.000Z', null, '2026-10-17T05:02:00.000Z'),
  ('n3', 'Canada Study Permit Document Checklist Revised', 'Documentation', 'Normal', 'We have updated the SOP guidelines and document checklist for Canadian study permit applications, including the new provincial attestation letter (PAL) requirement.', true, '2026-10-15T05:01:00.000Z', '2026-11-14T04:51:00.000Z', null, '2026-10-15T04:48:00.000Z'),
  ('n4', 'Germany Master’s Scholarship Opportunities', 'Scholarships', 'High', 'New merit scholarships are available for Master’s programmes at TU Munich for the Winter 2026 intake. Eligible students should apply before the priority deadline.', true, '2026-11-01T04:38:00.000Z', '2026-12-01T04:59:00.000Z', null, '2026-10-26T05:04:00.000Z'),
  ('n5', 'Scheduled System Maintenance', 'System Updates', 'Normal', 'The partner portal will be briefly unavailable on Saturday from 11:00 PM to 2:00 AM IST for scheduled maintenance.', false, '2026-11-03T04:49:00.000Z', '2026-11-05T05:17:00.000Z', null, '2026-10-27T04:41:00.000Z'),
  ('n6', 'Partner Excellence Awards 2025 — Winners', 'Events', 'Normal', 'Congratulations to all partners recognised at the annual Partner Excellence Awards. Thank you for an outstanding year.', true, '2026-08-29T04:39:00.000Z', '2026-10-08T04:50:00.000Z', null, '2026-08-28T04:54:00.000Z'),
  ('n7', 'Kerala Region: Monash Spot-Admission Day', 'Events', 'Medium', 'Monash University representatives will be at our Kochi office for on-the-spot assessments. Book your students’ slots through SSI Admissions.', true, '2026-10-25T04:51:00.000Z', '2026-11-09T04:53:00.000Z', ARRAY['p1']::text[], '2026-10-24T04:33:00.000Z')
